def esc(s): return html.escape(s, quote=False)
def box(t): return '<span class="exam-box en">' + t + '</span>'
def exam(no, stem, body_html): return '<b>' + str(no) + '. ' + stem + '</b>' + box(body_html)
def body(T): return ' '.join(esc(r[0]) for r in T)
def L(T, i): return T[i][0]

def mk(num, kind, T, real, vocab, pickv=(), tf=(), ilchi=(), pickg=(), verb=(), error=(), scr=(), order=(), insert=(), odd=(), blank=(), gram=(), summ=()):
    label = '%d번 · %s' % (num, kind)
    st = [{'type': 'vocab', 'title': '핵심어휘·숙어', 'quizN': min(10, len(vocab)), 'items': [[w, m, num] for w, m in vocab]},
          {'type': 'mc', 'title': '실전 문항', 'guide': '시험지 원문항이에요. 지문을 읽고 답을 고르세요.', 'items': [dict(real, n=num)]}]
    def add(lst, s):
        if lst: st.append(s)
    add(pickv, {'type': 'pick', 'title': '어휘선택', 'guide': '문맥에 맞는 낱말을 고르세요.', 'items': [{'s': s, 'ex': x} for s, x in pickv]})
    add(tf, {'type': 'tf', 'title': 'T/F 내용 확인', 'guide': '본문 내용과 일치하면 T, 다르면 F를 고르세요.', 'items': [[s, b, x, num, ev] for s, b, x, ev in tf]})
    add(ilchi, {'type': 'mc', 'title': '일치·불일치', 'guide': MCG, 'items': [dict(q, n=num, box=[label]) for q in ilchi]})
    add(pickg, {'type': 'pick', 'title': '어법선택', 'guide': '어법상 알맞은 것을 고르세요.', 'items': [{'s': s, 'ex': x} for s, x in pickg]})
    add(verb, {'type': 'verb', 'title': '동사변형', 'guide': '( ) 안의 동사를 알맞은 형태로 바꿔 쓰세요.', 'items': [{'s': s, 'v': v, 'a': a, 'ex': x} for s, v, a, x in verb]})
    add(error, {'type': 'error', 'title': '오류찾기', 'guide': '어법상 틀린 곳을 고르세요.', 'items': [{'s': s, 'w': w, 'fix': f, 'ex': x} for s, w, f, x in error]})
    add(scr, {'type': 'scramble', 'title': '본문 스크램블', 'guide': '우리말에 맞게 단어를 눌러 문장을 완성하세요.', 'items': [{'ko': T[i][1], 'en': T[i][0]} for i in scr]})
    add(order, {'type': 'order', 'title': '문장순서', 'guide': '문장을 본문 순서대로 눌러서 배열하세요.', 'items': [{'lines': [T[i][0] for i in idx], 'flow': f} for idx, f in order]})
    add(insert, {'type': 'insert', 'title': '문장삽입', 'guide': '주어진 문장이 들어가기에 가장 알맞은 곳을 고르세요.', 'items': [{'lines': [T[i][0] for i in idx], 'given': 1, 'flow': f, 'ex': x} for idx, f, x in insert]})
    add(odd, {'type': 'odd', 'title': '어색한 문장', 'guide': '글의 흐름과 관계없는 문장을 고르세요.', 'items': [{'lines': [T[a][0], T[b][0], o, T[c][0]], 'odd': 2, 'ex': x} for (a, b, c), o, x in odd]})
    add(blank, {'type': 'blank', 'title': '빈칸추론', 'guide': '빈칸에 들어갈 말로 가장 알맞은 것을 고르세요.', 'items': [{'s': s, 'opts': o, 'ex': x} for s, o, x in blank]})
    add(gram, {'type': 'mc', 'title': '핵심문법', 'guide': GV, 'items': [{'n': num, 'q': q, 'opts': o, 'ex': x} for q, o, x in gram]})
    add(summ, {'type': 'mc', 'title': '요약문 완성', 'guide': '지문을 읽고 요약문의 빈칸 (A), (B)에 들어갈 말을 고르세요.',
               'items': [{'n': num, 'box': [label], 'q': '다음 글의 내용을 한 문장으로 요약할 때, 빈칸 (A), (B)에 들어갈 말로 가장 알맞은 것은?<br><b>' + s + '</b>', 'opts': o, 'ex': x, 'ev': ev} for s, o, x, ev in summ]})
    return {'num': num, 'label': label, 'kind': kind, 'passage': [['#', label, '']] + [['', a, b] for a, b in T], 'steps': st}

